pub(crate) fn global_proc_addr(name: &CStr) -> PFN_vkVoidFunction {
    match name.to_bytes() {
        b"vkCreateInstance" => {
            erase_function(vkCreateInstance as vk::PFN_vkCreateInstance)
        }
        b"vkEnumerateInstanceExtensionProperties" => {
            erase_function(
                vkEnumerateInstanceExtensionProperties
                    as vk::PFN_vkEnumerateInstanceExtensionProperties,
            )
        }
        b"vkEnumerateInstanceLayerProperties" => {
            erase_function(
                vkEnumerateInstanceLayerProperties
                    as vk::PFN_vkEnumerateInstanceLayerProperties,
            )
        }
        b"vkEnumerateInstanceVersion" => {
            erase_function(
                vkEnumerateInstanceVersion as vk::PFN_vkEnumerateInstanceVersion,
            )
        }
        b"vkGetInstanceProcAddr" => {
            erase_function(vkGetInstanceProcAddr as vk::PFN_vkGetInstanceProcAddr)
        }
        _ => None,
    }
}
