pub(crate) const fn surface_create_info_extension_size(
    root: VkStructureType,
    structure_type: VkStructureType,
) -> Option<usize> {
    match (root, structure_type) {
        (
            VkStructureType::DISPLAY_SURFACE_CREATE_INFO_KHR,
            VkStructureType::DISPLAY_SURFACE_STEREO_CREATE_INFO_NV,
        ) => {
            Some(core::mem::size_of::<vk::VkDisplaySurfaceStereoCreateInfoNV<'static>>())
        }
        _ => None,
    }
}
