impl ExtensionSet {
    pub(crate) unsafe fn from_names(count: u32, names: *const *const c_char) -> Self {
        let mut set = Self::default();
        if names.is_null() {
            return set;
        }
        for index in 0..count as usize {
            let name = unsafe { names.add(index).read() };
            if !name.is_null()
                && let Some(id) = extension_id(unsafe { CStr::from_ptr(name) })
            {
                set.insert(id);
            }
        }
        set
    }
    fn insert(&mut self, id: u16) {
        let index = usize::from(id);
        debug_assert!(index < EXTENSION_NAMES.len());
        unsafe { *self.words.get_unchecked_mut(index / 64) |= 1_u64 << (index % 64) };
    }
    pub(crate) fn contains(&self, id: u16) -> bool {
        let index = usize::from(id);
        debug_assert!(index < EXTENSION_NAMES.len());
        (unsafe { *self.words.get_unchecked(index / 64) } & (1_u64 << (index % 64))) != 0
    }
    pub(crate) fn contains_name(&self, name: &CStr) -> bool {
        extension_id(name).is_some_and(|id| self.contains(id))
    }
}
#[cold]
fn extension_id(name: &CStr) -> Option<u16> {
    EXTENSION_NAMES
        .binary_search_by(|candidate| {
            unsafe { CStr::from_ptr(candidate.0) }.to_bytes().cmp(name.to_bytes())
        })
        .ok()
        .map(|id| id as u16)
}
#[cold]
pub(crate) fn is_known_instance_extension(name: &CStr) -> bool {
    let Some(id) = extension_id(name) else {
        return false;
    };
    let index = usize::from(id);
    (unsafe { *INSTANCE_EXTENSION_WORDS.get_unchecked(index / 64) }
        & (1_u64 << (index % 64))) != 0
}
#[cold]
pub(crate) fn wsi_instance_extension_supported(name: &CStr) -> bool {
    #[cfg(
        not(
            all(
                feature = "wsi-xlib",
                any(
                    target_os = "linux",
                    target_os = "freebsd",
                    target_os = "openbsd",
                    target_os = "netbsd",
                    target_os = "dragonfly",
                    target_os = "hurd",
                    target_os = "cygwin"
                )
            )
        )
    )]
    if name == vk::VK_KHR_XLIB_SURFACE_EXTENSION_NAME {
        return false;
    }
    #[cfg(
        not(
            all(
                feature = "wsi-xcb",
                any(
                    target_os = "linux",
                    target_os = "freebsd",
                    target_os = "openbsd",
                    target_os = "netbsd",
                    target_os = "dragonfly",
                    target_os = "hurd",
                    target_os = "cygwin"
                )
            )
        )
    )]
    if name == vk::VK_KHR_XCB_SURFACE_EXTENSION_NAME {
        return false;
    }
    #[cfg(
        not(
            all(
                feature = "wsi-wayland",
                any(
                    target_os = "linux",
                    target_os = "freebsd",
                    target_os = "openbsd",
                    target_os = "netbsd",
                    target_os = "dragonfly",
                    target_os = "hurd",
                    target_os = "cygwin"
                )
            )
        )
    )]
    if name == vk::VK_KHR_WAYLAND_SURFACE_EXTENSION_NAME {
        return false;
    }
    #[cfg(not(feature = "wsi-directfb"))]
    if name == vk::VK_EXT_DIRECTFB_SURFACE_EXTENSION_NAME {
        return false;
    }
    #[cfg(not(any(target_os = "nto", target_os = "qnx")))]
    if name == vk::VK_QNX_SCREEN_SURFACE_EXTENSION_NAME {
        return false;
    }
    true
}
